CREATE EXTENSION IF NOT EXISTS pgcrypto;
CREATE TABLE IF NOT EXISTS users (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), email text NOT NULL UNIQUE, password_hash text NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS organizations (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), name text NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS memberships (user_id uuid REFERENCES users(id) ON DELETE CASCADE, organization_id uuid REFERENCES organizations(id) ON DELETE CASCADE, role text NOT NULL CHECK(role IN ('owner','admin','member')), PRIMARY KEY(user_id, organization_id));
CREATE TABLE IF NOT EXISTS clients (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), organization_id uuid NOT NULL REFERENCES organizations(id) ON DELETE CASCADE, name text NOT NULL, email text, company text, phone text, status text NOT NULL DEFAULT 'active' CHECK(status IN ('active','archived')), created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS contacts (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), organization_id uuid NOT NULL REFERENCES organizations(id) ON DELETE CASCADE, client_id uuid REFERENCES clients(id) ON DELETE CASCADE, name text NOT NULL, email text, role text, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS deals (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), organization_id uuid NOT NULL REFERENCES organizations(id) ON DELETE CASCADE, client_id uuid REFERENCES clients(id) ON DELETE SET NULL, owner_id uuid REFERENCES users(id) ON DELETE SET NULL, title text NOT NULL, value numeric(12,2) NOT NULL DEFAULT 0, currency text NOT NULL DEFAULT 'USD', stage text NOT NULL DEFAULT 'lead' CHECK(stage IN ('lead','qualified','proposal','negotiation','won','lost')), close_date date, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS activities (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), organization_id uuid NOT NULL REFERENCES organizations(id) ON DELETE CASCADE, client_id uuid REFERENCES clients(id) ON DELETE CASCADE, deal_id uuid REFERENCES deals(id) ON DELETE CASCADE, user_id uuid REFERENCES users(id) ON DELETE SET NULL, type text NOT NULL CHECK(type IN ('call','meeting','email','follow_up')), title text NOT NULL, due_at timestamptz NOT NULL, completed boolean NOT NULL DEFAULT false, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS notes (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), organization_id uuid NOT NULL REFERENCES organizations(id) ON DELETE CASCADE, client_id uuid REFERENCES clients(id) ON DELETE CASCADE, author_id uuid REFERENCES users(id) ON DELETE SET NULL, body text NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS schema_migrations (name text PRIMARY KEY, applied_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX IF NOT EXISTS clients_org_idx ON clients(organization_id, created_at DESC); CREATE INDEX IF NOT EXISTS deals_org_stage_idx ON deals(organization_id, stage); CREATE INDEX IF NOT EXISTS activities_org_due_idx ON activities(organization_id, due_at);
